pub(crate) fn mark_dirty_at_and_after_index(&self, key: &[PathKey], index: usize) {
    let paths = {
        let read = self.inner.read_unchecked();
        let mut paths = Vec::new();
        read.root.paths_at_and_after_index(key, index, &mut paths);
