/// How deeply a reactive context is subscribed to a node in the [`StoreSubscriptions`] tree.
///
/// A shallow subscription is only notified when the exact node it points at changes. A deep
/// subscription is notified when the node it points at *or any of its descendants* changes. Deep
/// subscriptions are used whenever a raw reference to a value is handed out because the reader could
/// read any nested part of the value.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub(crate) enum SubscriptionDepth {
    /// Subscribe to only the exact path.
    Shallow,
    /// Subscribe to the exact path and all of its descendants.
    Deep,
}

impl SubscriptionDepth {
    /// Returns true if this subscription includes descendants of the path it points at.
    fn includes_deep(self) -> bool {
        matches!(self, SubscriptionDepth::Deep)
    }
}

impl BitOrAssign for SubscriptionDepth {
    /// Merge two subscription depths. A subscription that is deep in either operand stays deep.
    fn bitor_assign(&mut self, rhs: Self) {
        if rhs.includes_deep() {
            *self = SubscriptionDepth::Deep;
        }
    }
}

/// A single node in the [`StoreSubscriptions`] tree. Each path is a specific view into the store
/// and can be subscribed to and marked dirty separately. If the whole store is read or written to, all
/// nodes in the subtree are subscribed to or marked as dirty.
#[derive(Clone, Default)]
pub(crate) struct SelectorNode {
    subscribers: HashMap<ReactiveContext, SubscriptionDepth>,
    root: HashMap<PathKey, SelectorNode>,
}

impl SelectorNode {
    /// Get an existing selector node by its path.
    fn get(&self, path: &[PathKey]) -> Option<&SelectorNode> {
        let [first, rest @ ..] = path else {
            return Some(self);
        };
        self.root.get(first).and_then(|child| child.get(rest))
    }

    /// Get an existing selector node by its path mutably.
    fn get_mut(&mut self, path: &[PathKey]) -> Option<&mut SelectorNode> {
        let [first, rest @ ..] = path else {
            return Some(self);
        };
        self.root
            .get_mut(first)
            .and_then(|child| child.get_mut(rest))
    }

    /// Get a selector mutably or create one if it doesn't exist. This is used when subscribing to
    /// a path that may not exist yet.
    fn get_mut_or_default(&mut self, path: &[PathKey]) -> &mut SelectorNode {
        let [first, rest @ ..] = path else {
            return self;
        };
        self.root
            .entry(*first)
            .or_default()
            .get_mut_or_default(rest)
    }

    /// Add a subscriber to this node, merging the depth with any existing subscription for the same
    /// reactive context.
    fn add_subscriber(&mut self, subscriber: ReactiveContext, depth: SubscriptionDepth) {
        match self.subscribers.get_mut(&subscriber) {
            Some(existing) => *existing |= depth,
            None => {
                self.subscribers.insert(subscriber, depth);
            }
        }
    }

    /// Remove a subscriber from this node.
    fn remove_subscriber(&mut self, subscriber: &ReactiveContext) {
        self.subscribers.remove(subscriber);
    }

    /// A node is empty when it has no subscribers and no children.
    fn is_empty(&self) -> bool {
        self.subscribers.is_empty() && self.root.is_empty()
    }

    /// Recursively remove empty nodes along a path. Nodes are pruned from the deepest node upwards
    /// so that a node whose only child becomes empty is pruned as well.
    fn prune_if_empty(&mut self, path: &[PathKey]) {
        let [first, rest @ ..] = path else {
            return;
        };
        if let Some(child) = self.root.get_mut(first) {
            child.prune_if_empty(rest);
            if child.is_empty() {
                self.root.remove(first);
            }
        }
    }

    /// Get the path to each node under this node
    ///
    /// This is used to mark nodes dirty recursively when a Store is written to.
    fn paths_under(&self, current_path: &[PathKey], paths: &mut Vec<Box<[PathKey]>>) {
        paths.push(current_path.into());
        for (i, child) in self.root.iter() {
            let mut child_path: Vec<PathKey> = current_path.into();
            child_path.push(*i);
            child.paths_under(&child_path, paths);
        }
    }

    /// Get paths to only children at and after a certain index.
    ///
    /// This is used when inserting a new item into a list.
    /// Items after the index that is inserted need to be marked dirty because the value that index points to may have changed.
    fn paths_at_and_after_index(
        &self,
        path: &[PathKey],
        index: usize,
        paths: &mut Vec<Box<[PathKey]>>,
    ) {
        let Some(node) = self.get(path) else {
            return;
        };

        // Mark the nodes at and after the index as dirty
        for (i, child) in node.root.iter() {
            if *i as usize >= index {
                let mut child_path: Vec<PathKey> = path.into();
                child_path.push(*i);
                child.paths_under(&child_path, paths);
            }
        }
    }
}

