    #[test]
    fn scratch_behaviors() {
        let dom = VirtualDom::new(empty_app);
        dom.in_scope(ScopeId::ROOT, || {
            // sibling isolation + deep parent + arbitrarily deep upward
            let subs = StoreSubscriptions::new();
            let a = Arc::new(AtomicUsize::new(0));
            let ac = counting_context(a.clone());
            ac.subscribe(subs.deep_subscribers(&[])); // parent deep at root
            let sib = Arc::new(AtomicUsize::new(0));
            let sc = counting_context(sib.clone());
            sc.subscribe(subs.deep_subscribers(&[0])); // sibling deep at [0]
            // write to deeply nested [1,2,3]
            subs.mark_dirty(&[1, 2, 3]);
            assert_eq!(a.load(Ordering::Relaxed), 1, "root parent notified on deep write");
            assert_eq!(sib.load(Ordering::Relaxed), 0, "sibling [0] not notified");

            // vec index write vs push
            let vs = StoreSubscriptions::new();
            let whole = Arc::new(AtomicUsize::new(0));
            let wc = counting_context(whole.clone());
            wc.subscribe(vs.shallow_subscribers(&[])); // whole vec (iter/len => shallow at root)
            let idx = Arc::new(AtomicUsize::new(0));
            let ic = counting_context(idx.clone());
            ic.subscribe(vs.deep_subscribers(&[5])); // element index 5
            // index write => mark_dirty([5])
            vs.mark_dirty(&[5]);
            assert_eq!(whole.load(Ordering::Relaxed), 0, "whole-vec shallow NOT notified on index write");
            assert_eq!(idx.load(Ordering::Relaxed), 1, "index 5 notified on index write");
            // push => mark_node_dirty([]) (root vec)
            vs.mark_node_dirty(&[]);
            assert_eq!(whole.load(Ordering::Relaxed), 1, "whole-vec notified on push");
            assert_eq!(idx.load(Ordering::Relaxed), 1, "existing index NOT notified on push");
        });
    }

    #[test]
    fn scratch_readsignal_visit_remove() {
        let dom = VirtualDom::new(empty_app);
        dom.in_scope(ScopeId::ROOT, || {
            let subs = StoreSubscriptions::new();
            let p = Arc::new(AtomicUsize::new(0));
            let parent = counting_context(p.clone());
            // parent deep-subscribes at root; child lens is at [0]
            parent.subscribe(subs.deep_subscribers(&[]));
            let child_handle = subs.deep_subscribers(&[0]);
            // count visible via child handle
            let mut visible = 0;
            child_handle.visit(&mut |_rc: &ReactiveContext| visible += 1);
            assert_eq!(visible, 1, "exactly one parent deep subscriber visible from child");
            child_handle.remove(&parent);
            let mut visible2 = 0;
            child_handle.visit(&mut |_rc: &ReactiveContext| visible2 += 1);
            assert_eq!(visible2, 0, "no subscribers after remove");
        });
    }
